{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE spfclaims_final_new_spf_table_c AS WITH base AS ( SELECT *, CASE WHEN UPPER(TRIM(channel_name)) IN (\'SHOPIFY\', \'B2C-DELHIVERY\', \'B2C-PROZO\', \'B2C-EKART\', \'B2C PROZO\', \'B2C-BLUEDART\', \'B2C-BLITZ\') THEN \'SHOPIFY\' WHEN UPPER(TRIM(channel_name)) IN (\'SAPL_AJIO_OMNI_2\', \'SAPL_AJIO_OMNI_EMIZA\', \'SAPL_AJIO_OMNI\', \'AJIO\', \'MP_AJIO\') THEN \'AJIO\' WHEN UPPER(TRIM(channel_name)) IN (\'FLIPKART_SAPLWH2\', \'FLIPKART_SAPL\', \'FLIPKART\',\'MP-FLIPKART\', \'FLIPKART_SAPL_EMIZA\') THEN \'FLIPKART\' WHEN UPPER(TRIM(channel_name)) IN (\'MYNTRAPMP_SAPL-WH2\', \'SAPL_MYNTAPPMP\',\'SAPL_MYNTRAPPMP\', \'MP-MYNTRA\', \'SAPL_MYNTAPP_EMIZA\',\'MYNTRAPPMP_SAPL-WH2\',\'SAPL_MYNTRA_EMIZA\',\'MYNTRA\') THEN \'MYNTRA\' WHEN UPPER(TRIM(channel_name)) IN (\'AMAZON_FLEX_WH2\', \'AMAZON_FLEX_API_SAPL\', \'MP-AMAZON\', \'AMAZON\') THEN \'AMAZON\' WHEN UPPER(TRIM(channel_name)) IN (\'MP-NYKAA\', \'NYKAA_FASHION_WH2\', \'NYKAA_FASHION_WH\', \'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\', \'NYKAA\') THEN \'NYKAA\' WHEN UPPER(TRIM(channel_name)) = \'MP-CRED\' THEN \'CRED\' WHEN UPPER(TRIM(channel_name)) = \'GROO SHIP\' THEN \'GROO SHIP\' WHEN UPPER(TRIM(channel_name)) = \'DONOSHOP\' THEN \'DONOSHOP\' WHEN UPPER(TRIM(channel_name)) = \'BLUEDART\' THEN \'BLUEDART\' WHEN UPPER(TRIM(channel_name)) = \'SELFSHIP\' THEN \'SELFSHIP\' ELSE UPPER(TRIM(channel_name)) END AS cleaned_channel_name FROM spfclaims_final_new_spf_table WHERE received_date NOT IN (\'\', \'null\') ), cleaned AS ( SELECT CASE WHEN TRIM(CAST(ID AS TEXT)) IN (\'\', \'null\') THEN NULL ELSE ID END AS ID, TRY_TO_DATE(NULLIF(NULLIF(month, \'\'), \'null\'), \'DD-MM-YYYY\') AS month, TRY_TO_NUMBER(NULLIF(NULLIF(AGEING, \'\'), \'null\')) AS AGEING, NULLIF(NULLIF( CASE WHEN UPPER(TRIM(DONE_BY)) IN (\'PRADEEP\',\'P\') THEN \'PRADEEP\' WHEN UPPER(TRIM(DONE_BY)) IN (\'BAJARANGI\',\'B\') THEN \'BAJARANGI\' WHEN UPPER(TRIM(DONE_BY)) IN (\'RAMYA\',\'R\') THEN \'RAMYA\' WHEN UPPER(REPLACE(TRIM(DONE_BY),\'’\',\'\')) IN (\'CHANDAN\',\'C\') THEN \'CHANDAN\' WHEN UPPER(REPLACE(TRIM(DONE_BY),\'✓\',\'\')) IN (\'DHYAN\',\'D\') THEN \'DHYAN\' ELSE TRIM(DONE_BY) END, \'\'), \'null\') AS DONE_BY, NULLIF(NULLIF(REMARKS, \'\'), \'null\') AS REMARKS, NULLIF(NULLIF(WH_TYPE, \'\'), \'null\') AS WH_TYPE, CASE WHEN TRIM(CAST(TOTAL_QTY AS TEXT)) IN (\'\', \'null\') THEN NULL ELSE TOTAL_QTY END AS TOTAL_QTY, NULLIF(NULLIF(CREATED_BY, \'\'), \'null\') AS CREATED_BY, NULLIF(NULLIF(QC_COMMENT, \'\'), \'null\') AS QC_COMMENT, cleaned_channel_name AS channel_name, UPPER(NULLIF(NULLIF(tracking_no, \'\'), \'null\')) AS tracking_no, NULLIF(NULLIF(item_skucode, \'\'), \'null\') AS item_skucode, NULLIF(NULLIF(PHY_SKU_CODE, \'\'), \'null\') AS PHY_SKU_CODE, NULLIF(NULLIF(PUTAWAY_CODE, \'\'), \'null\') AS PUTAWAY_CODE, TRY_TO_DATE(NULLIF(NULLIF(QC_DONE_DATE, \'\'), \'null\'), \'DD-MM-YYYY\') AS QC_DONE_DATE, NULLIF(NULLIF(QC_VIDEO_LINK, \'\'), \'null\') AS QC_VIDEO_LINK, TRY_TO_DATE(NULLIF(NULLIF(received_date, \'\'), \'null\'), \'DD-MM-YYYY\') AS received_date, NULLIF(NULLIF(shipment_type, \'\'), \'null\') AS shipment_type, NULLIF(NULLIF(ticket_number, \'\'), \'null\') AS ticket_number, COALESCE( TRY_TO_DATE(NULLIF(NULLIF(ticket_raised_date, \'\'), \'null\'), \'DD-MM-YYYY\'), CAST(TRY_TO_TIMESTAMP(NULLIF(NULLIF(ticket_raised_date, \'\'), \'null\'), \'MON DD, YYYY HH12:MI AM\') AS DATE) ) AS ticket_raised_date, NULLIF(NULLIF(ticket_status, \'\'), \'null\') AS ticket_status, NULLIF(NULLIF(SALE_ORDER_CODE, \'\'), \'null\') AS SALE_ORDER_CODE, NULLIF(NULLIF(REJECTION_REASON, \'\'), \'null\') AS REJECTION_REASON, NULLIF(NULLIF(TICKET_RAISED_BY, \'\'), \'null\') AS TICKET_RAISED_BY, CASE WHEN TRIM(CAST(LAST_UPDATED_AT AS TEXT)) IN (\'\', \'null\') THEN NULL ELSE LAST_UPDATED_AT END AS LAST_UPDATED_AT, TO_TIMESTAMP(CAST(FLOOR(LAST_UPDATED_AT / 1000) AS NUMBER)) AS last_updated_at_readable, NULLIF(NULLIF(CONCAT_WS(\'_\', tracking_no, item_skucode), \'\'), \'null\') AS CONCATE1 FROM base WHERE NOT ( ( cleaned_channel_name = \'FLIPKART\' AND ( ( LOWER(qc_comment) LIKE \'%wpr%\' OR LOWER(qc_comment) LIKE \'%damage%\' OR LOWER(qc_comment) LIKE \'%damaged%\' OR LOWER(qc_comment) LIKE \'%dama%\' OR LOWER(qc_comment) LIKE \'%fake%\' OR LOWER(qc_comment) LIKE \'%fakr%\' OR LOWER(qc_comment) LIKE \'%faker%\' OR LOWER(qc_comment) LIKE \'%fakle%\' OR LOWER(qc_comment) LIKE \'%faqke%\' OR LOWER(qc_comment) LIKE \'%fske%\' OR LOWER(qc_comment) LIKE \'%fpr%\' OR LOWER(qc_comment) LIKE \'%wrong product%\' ) AND LOWER(qc_comment) NOT LIKE \'%partial%\' ) ) OR ( cleaned_channel_name = \'SHOPIFY\' AND ( ( LOWER(qc_comment) LIKE \'%wpr%\' OR LOWER(qc_comment) LIKE \'%wrong product%\' ) AND LOWER(qc_comment) NOT LIKE \'%partial%\' ) ) ) ), tagged AS ( SELECT *, CASE WHEN ticket_number IS NOT NULL THEN 1 WHEN LOWER(ticket_status) IN ( \'claim accepted\', \'claim denied\', \'pending\', \'accept\', \'approved\', \'dispute accepted\', \'claim accepted\', \'payment completed\', \'claim denied\', \'reject\', \'dispute not accepted\', \'not approved\', \'raised within tat\', \'under investigation\', \'open\', \'awaiting seller response\' ) THEN 1 ELSE 0 END AS ticket_raised_flag, CASE WHEN LOWER(ticket_status) IN (\'accept\', \'approved\', \'dispute accepted\', \'claim accepted\', \'payment completed\') THEN \'Approved\' WHEN LOWER(ticket_status) IN (\'claim denied\', \'reject\', \'dispute not accepted\', \'not approved\') THEN \'Rejected\' WHEN LOWER(ticket_status) IN (\'raised within tat\', \'under investigation\', \'open\', \'awaiting seller response\') THEN \'Under Investigation\' WHEN LOWER(ticket_status) IN (\'to be raised\', \'nf\', \'o\', \'#na\', \'pending\', \'0\') THEN \'Pending\' ELSE \'Unknown\' END AS ticket_status_bucket FROM cleaned ) SELECT MAX(ID) AS ID, tracking_no, item_skucode, MAX(month) AS month, MAX(AGEING) AS AGEING, ROUND(MAX(AGEING / 86400000), 1) AS AGEING_DAYS, MAX(DONE_BY) AS DONE_BY, MAX(REMARKS) AS REMARKS, MAX(ybr.WH_TYPE) AS WH_TYPE, MAX(TOTAL_QTY) AS TOTAL_QTY, MAX(CREATED_BY) AS CREATED_BY, MAX(QC_COMMENT) AS QC_COMMENT, MAX(CHANNEL_NAME) AS CHANNEL_NAME, MAX(QC_DONE_DATE) AS QC_DONE_DATE, MAX(ybr.QC_TIMESTAMP::DATE) AS qc_timestamp, MAX(PUTAWAY_CODE) AS PUTAWAY_CODE, MAX(RECEIVED_DATE) AS RECEIVED_DATE, MAX(t.SHIPMENT_TYPE) AS SHIPMENT_TYPE, MAX(TICKET_NUMBER) AS TICKET_NUMBER, MAX(TICKET_RAISED_DATE) AS TICKET_RAISED_DATE, MAX(TICKET_STATUS) AS TICKET_STATUS, MAX(ticket_raised_flag) AS ticket_raised_flag, MAX(ticket_status_bucket) AS ticket_status_bucket, MAX(REJECTION_REASON) AS REJECTION_REASON, MAX(TICKET_RAISED_BY) AS TICKET_RAISED_BY, MAX(last_updated_at_readable) AS last_update, MAX(t.LAST_UPDATED_AT) AS LAST_UPDATED_AT, FROM tagged t LEFT JOIN ylk_b2c_returns ybr ON t.tracking_no = ybr.awb GROUP BY tracking_no, item_skucode;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            